[1678] = { en = "Vejrek", tier = 1,
  t = "Vejrek",
  d = "Wil je hogerop komen bij de krijgers? Dan moet je taai zijn. Ik kan je nieuwe bewegingen leren. Maar eerst moet je bewijzen dat je jezelf kunt redden tegen echte vijanden.$B$BVejrek is de taaiste trol die je hier kunt vinden. Hem moet je verslaan. Hij heeft een hut in de heuvels net ten zuiden van Frostmane Hold.$B$BBreng me het hoofd van Vejrek. Dan weet ik dat je lef hebt.",
  o = "Breng Vejrek's Head naar Muren Stormpike in Ironforge.",
  p = "Ben je bij de hut van Vejrek geweest, $N? Ruik ik daar $R-stank aan je?",
  c = "Vejrek was echt een lelijke, hè? Goed gedaan, $N! Je hebt wat nodig is. Laten we nu met je les beginnen...$b$bMisschien weet je het niet, maar een sterke verdediging is heel belangrijk voor een $C. Zo blijft een $C staan tegen vijanden die anderen zouden neerslaan. En dat is wat je bondgenoten nodig hebben.",
  g = { {"hogerop komen", "to rise, to get ahead"}, {"taai", "tough"}, {"bewegingen", "moves (beweging)"}, {"bewijzen", "to prove"}, {"jezelf kunt redden", "can handle yourself (zich redden)"}, {"verslaan", "to beat, to defeat"}, {"heuvels", "foothills, hills (heuvel)"}, {"lef", "guts, mettle"}, {"stank", "stink"}, {"verdediging", "defense"}, {"neerslaan", "to knock down, to fell"}, {"bondgenoten", "allies (bondgenoot)"} },
},

[1680] = { en = "Tormus Deepforge", tier = 1,
  t = "Tormus Deepforge",
  d = "Je hebt nu een paar bewegingen geleerd. Tijd voor een goed wapen. Praat met Tormus Deepforge. Hij kan een wapen voor je maken. Ik weet zeker dat je het mooi vindt.$B$BJe vindt Tormus hier in Ironforge, bij de Great Forge.",
  o = "Praat met Tormus Deepforge.",
  c = "Heeft Muren je gestuurd? Ja, ik kan een mooi wapen voor je maken... maar eerst wil ik je om een gunst vragen.$b$bMaak je geen zorgen. Het is heel gevaarlijk en je kunt erdoor sterven. Het is precies het soort klus dat een $C wil.",
  g = { {"wapen", "weapon"}, {"gestuurd", "sent (sturen)"}, {"gunst", "favour"}, {"maak je geen zorgen", "don't worry"}, {"gevaarlijk", "dangerous"}, {"sterven", "to die"}, {"klus", "job, task"} },
},

[1681] = { en = "Ironband's Compound", tier = 1,
  t = "Het terrein van Ironband",
  d = "Mijn leermeester, Sturgy Ironband, had een terrein ten zuiden van Helm's Bed Lake, in het oosten van Dun Morogh. Daar gaf hij les in smeden, en hij was de beste.$B$BMaar op een dag bracht een van zijn leerlingen hem een lading vreemd erts. Meester Ironband noemde het Umbral Ore. Hij wilde er graag mee werken. Maar kort nadat het erts aankwam... viel een groep Dark Iron-dwergen zijn terrein aan. Ze vermoordden iedereen!$B$BGa het terrein van Ironband binnen, $N, en wreek de dood van mijn meester. En breng me de lading Umbral Ore die het veroorzaakte.",
  o = "Breng een lading Umbral Ore naar Tormus Deepforge in Ironforge.",
  p = "Ben je in Ironband's Compound geweest? Heb je de Umbral Ore gevonden?",
  c = "Je hebt het gevonden! Goed gedaan!$b$bIk hoop dat je onderweg een heleboel Dark Iron-dwergen hebt gedood. Ik ben bang dat we ze niet voor het laatst bij het terrein van Ironband hebben gezien.$b$bMaar bedankt voor het erts, $N. Ik wil er graag mee werken en ontdekken wat de eigenschappen zijn.",
  g = { {"leermeester", "mentor, master"}, {"terrein", "compound, grounds"}, {"smeden", "blacksmithing, to forge"}, {"lading", "load"}, {"erts", "ore"}, {"aankwam", "arrived (aankomen)"}, {"viel ... aan", "attacked (aanvallen)"}, {"vermoordden", "murdered (vermoorden)"}, {"wreek", "avenge (wreken)"}, {"veroorzaakte", "caused (veroorzaken)"}, {"onderweg", "on the way"}, {"een heleboel", "a whole lot"}, {"eigenschappen", "properties (eigenschap)"} },
},

[1641] = { en = "The Tome of Divinity", tier = 1,
  t = "Het boek van goddelijkheid",
  c = "Hier in Stormwind is het mijn taak om paladijnen op weg te helpen naar meer deugd. Zij geven zich aan het Licht en beschermen Azeroth tegen de Scourge en andere gevaren.$B$BHet is tijd voor je eerste stap om echt deugdzaam te worden. Als je het aanneemt, geef ik je een Book of Divinity. Als je het bestudeert, leer je iets over het Licht, en over wat er van je verwacht wordt. Als je het begrijpt en als je het kunt, krijg je sterkere vaardigheden.",
  g = { {"goddelijkheid", "divinity"}, {"paladijnen", "paladins (paladijn)"}, {"op weg te helpen", "to put on the path (op weg helpen)"}, {"deugd", "virtue"}, {"geven zich", "devote themselves (zich geven)"}, {"gevaren", "threats, dangers (gevaar)"}, {"deugdzaam", "virtuous"}, {"aanneemt", "accept (aannemen)"}, {"bestudeert", "study (bestuderen)"}, {"verwacht", "expected (verwachten)"}, {"vaardigheden", "abilities (vaardigheid)"} },
},

[1642] = { en = "The Tome of Divinity", tier = 1,
  t = "Het boek van goddelijkheid",
  d = "In alles moet een paladijn het Licht laten zien. Het Licht maakt ons sterker. Als iemand zoals wij goddelijk wil zijn, betekent dat niet dat we een god willen worden. We willen goed zijn in alles wat we doen.$B$BIn deze harde tijden moeten we het kwaad verslaan. Maar onthoud altijd: vooral door anderen te helpen, ben je echt anders dan de andere burgers van Azeroth. Medeleven, geduld, moed: die dingen zijn voor een paladijn net zo belangrijk als kracht in de strijd.$B$BWeet dit goed, en vergeet het nooit.",
  o = "Praat met Duthorian Rall in Stormwind.",
  c = "Hallo weer, $N. Hoe gaat het met je studie van het Tome of Divinity?$B$BDan moet je klaar zijn om getest te worden. Er is altijd werk te doen in de stad en in onze landen: daden van medeleven en begrip, mensen die hulp nodig hebben, wezens om te doden.$B$BAls je laat zien dat je het geduld hebt om anderen te helpen, vooral mensen met minder geluk, dan bewijs je dat je een dienaar van het Licht bent, met een helder hoofd.",
  g = { {"goddelijk", "divine"}, {"kwaad", "evil"}, {"onthoud", "remember (onthouden)"}, {"burgers", "citizens (burger)"}, {"medeleven", "compassion"}, {"geduld", "patience"}, {"moed", "bravery, courage"}, {"strijd", "battle"}, {"studie", "study, studies"}, {"daden", "deeds, acts (daad)"}, {"begrip", "understanding"}, {"wezens", "creatures (wezen)"}, {"dienaar", "servant"}, {"een helder hoofd", "a clear mind, of sound mind"} },
},

[1643] = { en = "The Tome of Divinity", tier = 1,
  t = "Het boek van goddelijkheid",
  d = "Jouw taak is dan, $N, om hier in Stormwind iemand te vinden die hulp nodig heeft. Iemand met een zuiver hart en zuivere bedoelingen. Misschien iemand die anderen helpt. Misschien iemand die een gids nodig heeft. Hoe dan ook, deze persoon moet edele bedoelingen hebben en op jouw goedheid rekenen.$B$BDoe dit en kom terug als je klaar bent. Dan praten we verder over je pad, en over wat het betekent om een paladijn van het Licht te zijn.",
  o = "Zoek in het Trade District van Stormwind naar Stephanie Turner.",
  c = "O, hallo, lieverd. Hoe gaan je avonturen? O, wat fijn dat het goed met je gaat.$B$BEn ik? Dank je dat je het vraagt. Met mij gaat het goed, als je alles bij elkaar neemt.$B$BEr zijn veel meer handelaren gekomen. Daardoor willen mensen nu minder leer en stof weggeven. Het is dus moeilijker om kleren te maken voor de kinderen in het weeshuis. Maar het lukt ons wel. Met \"ons\" bedoel ik mijn man en mij. Hij is in Ironforge en vraagt de burgers daar om hulp.",
  g = { {"zuiver", "pure"}, {"bedoelingen", "intentions, motives (bedoeling)"}, {"gids", "guide"}, {"hoe dan ook", "regardless"}, {"edele", "noble"}, {"goedheid", "kindness, goodness"}, {"rekenen op", "to rely on"}, {"lieverd", "love, dear"}, {"avonturen", "adventures (avontuur)"}, {"als je alles bij elkaar neemt", "all things considered"}, {"handelaren", "tradesmen, traders (handelaar)"}, {"leer", "leather"}, {"weggeven", "to give away, to part with"}, {"weeshuis", "orphanage"} },
},

