[1647] = { en = "The Tome of Divinity", tier = 1,
  t = "Het boek van goddelijkheid",
  d = "Jouw taak is dan, $N, om hier in Ironforge iemand te vinden die hulp nodig heeft. Iemand met een zuiver hart en zuivere bedoelingen. Misschien iemand die anderen helpt. Misschien iemand die een gids nodig heeft. Hoe dan ook, deze persoon moet edele bedoelingen hebben en op jouw goedheid rekenen.$B$BDoe dit en kom terug als je klaar bent. Dan praten we verder over je pad, en over wat het betekent om een paladijn van het Licht te zijn. Ik blijf hier in de tempel tot je terugkomt. Andere paladijnen hebben mijn begeleiding ook nodig.",
  o = "Zoek in de buitenste ring van Ironforge naar John Turner.",
  c = "HET WEESHUIS VAN STOR... o, sorry, ik wilde niet tegen je schreeuwen, $gmeneer:mevrouw;.$B$BIk heet John Turner. Hoe gaat het met je?$B$BGoed, goed, fijn om te horen dat het goed met je gaat. Ik heb al een lange werkdag achter de rug, en ik mis mijn vrouw heel erg. Maar dat is de prijs die je betaalt als er monden te voeden en ruggen te kleden zijn.",
  g = { {"zuiver", "pure"}, {"bedoelingen", "intentions, motives (bedoeling)"}, {"gids", "guide"}, {"edele", "noble"}, {"goedheid", "kindness, goodness"}, {"tempel", "temple"}, {"begeleiding", "guidance"}, {"buitenste", "outer"}, {"schreeuwen", "to shout"}, {"achter de rug", "behind me, done"}, {"monden", "mouths (mond)"}, {"voeden", "to feed"}, {"ruggen", "backs (rug)"}, {"kleden", "to clothe"} },
},

[1789] = { en = "The Symbol of Life", tier = 1,
  t = "Het symbool van het leven",
  c = "Schiet op, $N. Als het je niet lukt, staat er meer dan één leven op het spel.$B$BAls het je om een of andere reden niet lukt om Muiredon en Narm te helpen, kom dan terug naar mij. Dan geef ik je een nieuwe Symbol of Life voor je reis.$B$BDenk niet dat mijn hulp gewoon liefdadigheid is. Je moet laten zien dat je het waard bent, net als elke andere $C. Als het je steeds niet lukt, kan dat later slecht voor je zijn.",
  g = { {"symbool", "symbol"}, {"schiet op", "make haste (opschieten)"}, {"op het spel", "at stake"}, {"om een of andere reden", "for some reason"}, {"liefdadigheid", "charity"}, {"waard", "worthy, worth"}, {"steeds", "again and again, continually"} },
},

[1790] = { en = "The Symbol of Life", tier = 1,
  t = "Het symbool van het leven",
  c = "Schiet op, $N. Als het je niet lukt, staat er meer dan één leven op het spel.$B$BAls het je om een of andere reden niet lukt om Gazin en Henze te helpen, kom dan terug naar mij. Dan geef ik je een nieuwe Symbol of Life voor je reis.$B$BDenk niet dat mijn hulp gewoon liefdadigheid is. Je moet laten zien dat je het waard bent, net als elke andere $C. Als het je steeds niet lukt, kan dat later slecht voor je zijn.",
