[2997] = { en = "Tome of Divinity", tier = 1,
  t = "Het boek van goddelijkheid",
  d = "Hallo, $N. Ik weet dat je druk bezig bent om de mensen van Dun Morogh te helpen. Maar als je tijd hebt, moet je naar Ironforge gaan. Praat daar met een van de meest gerespecteerde mensen van ons soort: Tiza Battleforge. Naar haar gaan de jongere paladijnen als het tijd is om meer te leren over het Licht, en over wat er van je verwacht wordt.$B$BJe vindt haar boven in de Hall of Mysteries. Ben je daar nog nooit geweest? Die is in de Mystic Ward. Veel succes, hoor, $N.",
  o = "Praat met Tiza Battleforge in Ironforge.",
  c = "Gegroet, $N. Ik hoop dat het Licht je het ware pad laat zien en je beschermt tegen het kwaad.",
  g = { {"druk bezig", "busy"}, {"gerespecteerde", "respected"}, {"van ons soort", "of our kind, our ilk"}, {"jongere", "younger"}, {"boven", "upstairs"}, {"gegroet", "well met, greetings"}, {"ware", "true"}, {"pad", "path"}, {"beschermt", "protects (beschermen)"} },
},

[2998] = { en = "Tome of Divinity", tier = 1,
  t = "Het boek van goddelijkheid",
  d = "Gegroet, $Gbroeder:zuster;. Duthorian Rall, een van onze invloedrijkste paladijnen, had het pas over jou. Ik hoorde hem zeggen dat het tijd was om je een beetje op de proef te stellen... En hij zei ook heel positieve dingen over hoe goed je het tot nu toe hebt gedaan.$B$BAls ik jou was, zou ik naar Stormwind gaan en met hem praten als je tijd hebt. Hij is vast in de Cathedral of Light. Daar is hij het grootste deel van de tijd.",
  o = "Praat met Duthorian Rall in Stormwind.",
  c = "Het is mooi hier in Stormwind, vind je niet?$B$BEigenlijk kom je precies op het goede moment, $N.",
  g = { {"broeder", "brother (religious)"}, {"zuster", "sister (religious)"}, {"invloedrijkste", "most influential"}, {"had het over", "was talking about (het hebben over)"}, {"pas", "recently, just"}, {"op de proef te stellen", "to put to the test (op de proef stellen)"}, {"positieve", "positive, complimentary"}, {"tot nu toe", "so far"}, {"het grootste deel", "most (of)"}, {"precies", "exactly"} },
},

[2999] = { en = "Tome of Divinity", tier = 1,
  t = "Het boek van goddelijkheid",
  d = "Hallo, $N. Ik weet dat je druk bezig bent om de mensen van Dun Morogh te helpen. Maar als je tijd hebt, moet je naar boven gaan en praten met een van de meest gerespecteerde mensen van ons soort: Tiza Battleforge. Naar haar gaan de jongere paladijnen als het tijd is om meer te leren over het Licht, en over wat er van je verwacht wordt.",
  o = "Praat met Tiza Battleforge in Ironforge",
  c = "Gegroet, $N. Ik hoop dat het Licht je het ware pad laat zien en je beschermt tegen het kwaad.",
  g = { {"druk bezig", "busy"}, {"naar boven", "upstairs"}, {"gerespecteerde", "respected"}, {"van ons soort", "of our kind, our ilk"}, {"jongere", "younger"}, {"gegroet", "well met, greetings"}, {"ware", "true"}, {"beschermt", "protects (beschermen)"} },
},

[3000] = { en = "Tome of Divinity", tier = 1,
  t = "Het boek van goddelijkheid",
  d = "Hallo, $N. Ik weet dat je druk bezig bent om de mensen van Azeroth te helpen. Maar als je tijd hebt, moet je teruggaan naar Ironforge. Praat daar met een van de meest gerespecteerde paladijnen van je thuis: Tiza Battleforge. Naar haar gaan de jongere dwergpaladijnen als het tijd is om meer te leren over het Licht, en over wat er van ons allemaal verwacht wordt.$B$BJe vindt haar boven in de Hall of Mysteries. Die ligt in de Mystic Ward.",
  o = "Praat met Tiza Battleforge in Ironforge.",
  c = "Ik groet je en heet je welkom, $N.",
  g = { {"druk bezig", "busy"}, {"teruggaan", "to go back"}, {"gerespecteerde", "respected"}, {"thuis", "home"}, {"dwergpaladijnen", "dwarven paladins"}, {"verwacht", "expected (verwachten)"}, {"boven", "upstairs"}, {"heet je welkom", "bid you welcome (welkom heten)"} },
},

[3681] = { en = "Tome of Divinity", tier = 1,
  t = "Het boek van goddelijkheid",
  d = "Sorry dat ik je reis onderbreek, $r. Maar ik vond dat je moest weten dat er pas een bericht uit Stormwind kwam. Paladijnen moeten zich daar melden voor training.$B$BAls ik het niet beter wist, zou ik zeggen dat je bijna bij een speciaal moment bent. Het is tijd dat je de boeken gaat bestuderen.$B$BZoek Duthorian Rall in Stormwind. Hij traint paladijnen meestal in de Cathedral of Light.",
  o = "Praat met Duthorian Rall in Stormwind.",
  c = "Welkom in de Cathedral of Light, $C.",
  g = { {"onderbreek", "interrupt (onderbreken)"}, {"bericht", "message, word"}, {"zich melden", "to report"}, {"als ik het niet beter wist", "if I didn't know any better"}, {"speciaal", "special"}, {"bestuderen", "to study"}, {"traint", "trains (trainen)"}, {"meestal", "usually"} },
},

[1644] = { en = "The Tome of Divinity", tier = 1,
  t = "Het boek van goddelijkheid",
  d = "Die lieve schatten. De meesten hebben geen familie meer, door de aanvallen van de Scourge in de laatste tien jaar.$B$BMijn man John verzamelt de materialen voor mij. Daarmee maak ik de shirts en broeken voor de kinderen. Maar ik heb daar nog niet eens tijd voor gehad. Ik was te druk met eten op hun bord en een dak boven hun hoofd.$B$BWat zeg je? Wil je helpen? O, het Licht zij dank, en dank je wel, $N.$B$BKun je me wat linnen brengen? Dan kan ik kleren naaien voor de kinderen. Dat zou me zo veel helpen.",
  o = "Breng 10 Linen Cloth naar Stephanie Turner in Stormwind.",
  p = "Ik hoop dat mijn John meer geluk heeft in Ironforge. Hij gaat daar niet graag naartoe, want dan zijn de kinderen en ik alleen. Maar hij weet dat het moet. Hij heeft zo'n goed hart.$B$BSommige jaren waren makkelijker dan andere, maar dit jaar is veruit het zwaarste. Het is bijna alsof er iets in de lucht hangt dat een grote verandering aankondigt. Maar wie weet?",
  c = "Dank je, $N, heel erg bedankt!$B$BDe kinderen zullen zo blij zijn, en jij hebt mij zo veel tijd bespaard. Nu kan ik me richten op de andere dingen die de kinderen nodig hebben. En hopelijk kan mijn John eerder naar huis komen dan we dachten.$B$BNogmaals bedankt, $N. Ik wist dat ik op de goedheid van anderen kon rekenen. Het Licht zij met je.",
  g = { {"lieve schatten", "dear little ones, bless their hearts"}, {"aanvallen", "attacks (aanval)"}, {"broeken", "trousers, pants (broek)"}, {"een dak boven hun hoofd", "a roof over their heads"}, {"het Licht zij dank", "thank the Light"}, {"linnen", "linen"}, {"naaien", "to sew"}, {"veruit", "by far"}, {"het zwaarste", "the hardest, roughest"}, {"aankondigt", "signals, announces (aankondigen)"}, {"bespaard", "saved (besparen)"}, {"me richten op", "to focus on (zich richten op)"}, {"hopelijk", "hopefully"}, {"nogmaals", "once again"}, {"zij met je", "be with you"} },
},

[1648] = { en = "The Tome of Divinity", tier = 1,
  t = "Het boek van goddelijkheid",
  d = "Mijn vrouw en ik hebben een weeshuis in Stormwind. Het is vooral voor kinderen die hun ouders hebben verloren door de aanvallen van de Scourge in de laatste tien jaar. Ik kom ongeveer elke maand naar Ironforge. Dan probeer ik meer spullen te verzamelen bij de burgers hier. Ik praat ook met verschillende groepen, om te zien of ze iets kunnen doen om te helpen.$B$BDeze reis gaat vreselijk langzaam, en hij levert niet veel op.$B$BAls ik maar wat meer linnen kon krijgen, dan kan mijn vrouw kleren maken. Dan kan ik eindelijk een zending naar huis sturen.",
  o = "Breng 10 Linen Cloth naar John Turner in Ironforge.",
  p = "Er zijn hier en in heel Azeroth veel meer handelaren gekomen. Daardoor zijn er minder spullen om kleren te maken voor de kinderen in ons weeshuis. Je helpt me linnen te verzamelen, zodat mijn vrouw nieuwe kleren voor ze kan maken. Dat is heel edel van je, $N. Dank je.$B$BHopelijk kan ik snel terug naar huis, naar mijn vrouw.",
  c = "Dit is zo geweldig van je, $N. Nogmaals bedankt.$B$BJe bent een edele $gman:vrouw;, omdat je dit voor me doet. Geen wonder dat je het Licht volgt. Ik wou dat ik je kon terugbetalen voor alles wat je hebt gedaan... wat zeg je? Dat is het minste wat je kon doen? Zie je? Dat bedoel ik nou, $N: edel tot het einde.$B$BWees voorzichtig, en moge het Licht je beschermen op je reizen.",
  g = { {"weeshuis", "orphanage"}, {"verloren", "lost (verliezen)"}, {"ongeveer", "about, or so"}, {"verschillende", "various"}, {"vreselijk", "terribly, agonizingly"}, {"levert ... op", "yields, produces (opleveren)"}, {"zending", "shipment"}, {"handelaren", "tradesmen (handelaar)"}, {"edel", "noble"}, {"geen wonder", "no wonder"}, {"terugbetalen", "to repay"}, {"het minste", "the least"}, {"tot het einde", "to the end"} },
},

[1698] = { en = "Yorus Barleybrew", tier = 1,
  t = "Yorus Barleybrew",
  d = "Yorus Barleybrew heeft alle sterke krijgers van de Alliance uitgedaagd. Hij wacht in de Lakeshire Inn, in Redridge. Hij belooft een grote beloning aan iedereen die zijn proef haalt.",
  o = "Praat met Yorus Barleybrew.",
  c = "Ha! Dus je hebt van mijn uitdaging gehoord?$B$BNou, ga zitten en luister. Neem een drankje en geniet ervan... want het kan je laatste zijn.",
  g = { {"uitgedaagd", "challenged (uitdagen)"}, {"belooft", "promises (beloven)"}, {"beloning", "reward"}, {"proef", "trial, test"}, {"haalt", "passes (halen)"}, {"uitdaging", "challenge"}, {"geniet ervan", "enjoy it, savour it (genieten)"} },
},

[1699] = { en = "The Rethban Gauntlet", tier = 2,
  t = "De Rethban Gauntlet",
  d = "Ik noem mijn uitdaging de Rethban Gauntlet. Om de proef te halen, hoef je alleen maar de Rethban Caverns in te gaan tot de eerste splitsing, en dan hier terug te komen. Makkelijk! Alleen zijn er een paar lastige dingetjes...$B$BJe moet binnen een uur terug zijn.$B$BEr staan hele hopen Redridge Gnolls in de weg.$B$BEn voordat je begint, moet je een slok nemen van het bekende drankje van mijn familie: Barleybrew Scalder!$B$BWat zeg je ervan? De Rethban Caverns liggen in de heuvels ten noorden van Lakeshire. Ben je klaar om de Rethban Gauntlet te lopen?",
  o = "Ga de Rethban Caverns binnen, kom bij de eerste splitsing en ga binnen de tijd terug naar Yorus Barleybrew.$B$BJe mag niet sterven en je geest vrijlaten.",
  p = "De tijd tikt door, $n. Als ik jou was, zou ik opschieten...",
  c = "Het is je gelukt! Goed gedaan! Drie keer hoera voor $N!",
  e = "Ga de Rethban Caverns binnen",
  g = { {"splitsing", "fork (in a path)"}, {"lastige dingetjes", "tricky little things, catches"}, {"binnen een uur", "within an hour"}, {"hopen", "heaps (hoop)"}, {"in de weg", "in the way"}, {"slok", "swig, sip"}, {"wat zeg je ervan", "what do you say"}, {"geest", "spirit"}, {"vrijlaten", "to release"}, {"tikt door", "keeps ticking (doortikken)"}, {"opschieten", "to hurry up"}, {"hoera", "hooray, cheers"} },
},

[1702] = { en = "The Shieldsmith", tier = 2,
  t = "De schildsmid",
  d = "Je hebt echt laten zien wat je kunt, toen je de Rethban Gauntlet liep, $N. En ik houd mijn woord. Ik regel de beloning die ik beloofde...$B$BAlleen ligt die in Stormwind.$B$BPraat met mijn vriend Furen Longbeard, in het Dwarven District van Stormwind. Hij is de beste schildsmid die je ooit zult ontmoeten, en hij is me nog een grote gunst schuldig.$B$BHier, breng Furen dit vat Barleybrew Scalder en vraag hem om een schild. Hij geeft je een mooi exemplaar.",
  o = "Breng de Cask of Scalder naar Furen Longbeard.",
  p = "Hallo! Droge tijden, vind je niet?",
  c = "Ah, Barleybrew Scalder. Geweldig spul! Dus je bent bij Yorus geweest, hè?$B$BIk kan een schild voor je regelen, jazeker! Een beter schild vind je nergens, en dat is niet gelogen!",
  g = { {"ik houd mijn woord", "I keep my word"}, {"regel", "arrange, sort out (regelen)"}, {"beloofde", "promised (beloven)"}, {"schildsmid", "shieldsmith"}, {"ontmoeten", "to meet"}, {"schuldig", "owing, in debt"}, {"vat", "cask, barrel"}, {"exemplaar", "one, specimen"}, {"droge", "dry"}, {"spul", "stuff"}, {"jazeker", "yes indeed"}, {"niet gelogen", "no lie (liegen)"} },
},

[1700] = { en = "Grimand Elmore", tier = 2,
  t = "Grimand Elmore",
  d = "Ik heb een kopie gemaakt van mijn aantekeningen over de technieken die ik leerde toen ik je harnas maakte. Ik wil dat ze naar Grimand Elmore gaan. Hij is hier in het Dwarven District, in de wapenwinkel.$B$BEn duik weg als je ze aan hem geeft. Hij is ontzettend trots op zijn vakmanschap, en hij vindt het vast geen prettig idee om iets van mij te leren...",
  o = "Breng Furen's Notes naar Grimand Elmore.",
  p = "Hallo, en welkom. Waarmee kan ik je van dienst zijn?",
  c = "Heeft Furen dit geschreven? Hoe durft hij! Ik heb hem alles geleerd wat hij weet! Dat hij mij iets zou kunnen leren, is schandalig! Schandalig!$B$BHm... maar er staat wel iets in zijn aantekeningen dat ik zou willen proberen...",
  g = { {"kopie", "copy"}, {"aantekeningen", "notes (aantekening)"}, {"technieken", "techniques (techniek)"}, {"harnas", "armour"}, {"wapenwinkel", "weapon shop"}, {"duik weg", "duck (wegduiken)"}, {"ontzettend", "extremely, fiercely"}, {"vakmanschap", "craftsmanship, skills"}, {"prettig", "pleasant, nice"}, {"van dienst zijn", "to be of service"}, {"hoe durft hij", "how dare he (durven)"}, {"schandalig", "outrageous, scandalous"} },
},

[1701] = { en = "Fire Hardened Mail", tier = 2,
  t = "Vuurgeharde maliën",
  d = "Ik heb je dus een mooi schild gegeven, maar we hoeven daar niet te stoppen. Ik ken de geheimen om heel harde maliënkolders te maken. Het is niet makkelijk, en er zijn heel zeldzame materialen voor nodig. Maar als jij het loopwerk wilt doen, maak ik er een stuk voor je.$B$BWat zeg je ervan, $N? Als je de uitdaging aandurft, geef ik je een lijst van wat je moet halen en waar je het kunt vinden.",
  o = "Verzamel de materialen die Furen Longbeard nodig heeft en breng ze naar hem in Stormwind.",
  p = "Hoe gaat de speurtocht, $N? Heb je de materialen?",
  c = "Heb je alles? Geweldig! Ik was bang dat die chimaera's je zeker zouden opeten!$B$BNou, laten we aan dat harnas beginnen...",
  g = { {"vuurgeharde", "fire-hardened"}, {"maliën", "mail (armour)"}, {"geheimen", "secrets (geheim)"}, {"maliënkolders", "mail shirts, mail armour (maliënkolder)"}, {"zeldzame", "rare"}, {"materialen", "materials (materiaal)"}, {"loopwerk", "legwork"}, {"aandurft", "dare to take on (aandurven)"}, {"verzamel", "gather (verzamelen)"}, {"speurtocht", "scavenger hunt"}, {"opeten", "to eat up"} },
},

[1703] = { en = "Mathiel", tier = 2,
  t = "Mathiel",
  d = "Ik heb een kopie gemaakt van mijn aantekeningen over de technieken die ik leerde toen ik je harnas maakte. Ze moeten naar de smid Mathiel. Hij woont in Darnassus, en dat is een heel eind weg. Maar ik weet zeker dat hij heel dankbaar zal zijn om te leren wat ik heb geleerd.",
  o = "Breng Furen's Notes naar Mathiel.",
  p = "Ik groet je, $C.",
  c = "Deze zijn interessant, echt heel interessant. Mijn collega Furen, de dwerg, heeft een flinke ontdekking gedaan!$B$BDank je, $N. Het wordt een eer om zijn nieuwe technieken te gebruiken bij mijn eigen werk.",
  g = { {"smid", "blacksmith"}, {"een heel eind weg", "quite a long way off"}, {"dankbaar", "grateful"}, {"groet", "greet (groeten)"}, {"collega", "colleague"}, {"flinke", "considerable, big"}, {"ontdekking", "discovery"}, {"eer", "honour"} },
},

[1704] = { en = "Klockmort Spannerspan", tier = 2,
  t = "Klockmort Spannerspan",
  d = "Ik heb een kopie gemaakt van mijn aantekeningen over de technieken die ik leerde toen ik je harnas maakte. Ik zoek iemand die ze naar Klockmort Spannerspan brengt. Hij is een gnomensmid in Ironforge. Als hij leert wat ik heb geleerd... dan trekt hij van opwinding vast zijn eigen baard uit.",
  o = "Breng Furen's Notes naar Klockmort Spannerspan.",
  p = "Goedendag, of goedemorgen, of goedenavond. Ik kan het van hier beneden niet zien. Heb je zaken voor me?",
  c = "O jee! Deze aantekeningen zijn geweldig! En wat meer is... ze zijn ongelofelijk en ze zijn fantastisch en mijn knieën gaan er helemaal van trillen!$B$BFuren heeft een doorbraak! Een echte doorbraak! Ik kan niet wachten om zijn nieuwe techniek uit te proberen!",
  g = { {"gnomensmid", "gnomish blacksmith"}, {"opwinding", "excitement"}, {"baard", "beard"}, {"trekt ... uit", "pulls out (uittrekken)"}, {"zaken", "business (zaak)"}, {"ongelofelijk", "incredible"}, {"knieën", "knees (knie)"}, {"trillen", "to wobble, to shake"}, {"doorbraak", "breakthrough"}, {"uit te proberen", "to try out (uitproberen)"} },
},

[1705] = { en = "Burning Blood", tier = 2,
  t = "Brandend bloed",
  d = "Ik geef het niet graag toe, maar misschien heeft Furen echt iets gevonden. Om het zeker te weten, moet ik zijn technieken op een nieuw harnas proberen. Als je me helpt met de materialen, $N, mag jij het harnas hebben.$B$BVoor dit harnas heb ik monsters Burning Blood nodig, en een Burning Rock.$B$BDe enige plek die ik ken om ze te halen, is Duskwood. De Nightbane-worgen in de mijn Roland's Doom hebben Burning Blood. Hun leider Gutspill heeft de steen.$B$BMoge het geluk je snelheid geven, $N.",
  o = "Breng 20 flesjes Burning Blood en 1 Burning Rock naar Grimand Elmore in Stormwind.",
  p = "$N, heb je het Burning Blood en de steen? Ik heb ze nodig om het harnas af te maken.",
  c = "Goed werk! En nu, als je me wilt excuseren, ik heb zelf ook werk te doen...",
  g = { {"brandend", "burning"}, {"geef ... toe", "admit (toegeven)"}, {"om het zeker te weten", "to be sure"}, {"monsters", "samples (monster)"}, {"mijn", "mine (for ore)"}, {"leider", "leader"}, {"moge", "may (wish)"}, {"geluk", "fortune, luck"}, {"snelheid", "speed"}, {"flesjes", "vials (flesje)"}, {"excuseren", "to excuse"} },
},

[1708] = { en = "Iron Coral", tier = 2,
  t = "IJzeren koraal",
  d = "Ik wil de nieuwe technieken van Furen Longbeard op mijn eigen harnas proberen. En omdat jij Furen hebt geholpen en hij mij heeft geholpen, mag jij het harnas hebben als ik het gemaakt heb!$B$BOm het af te maken, heb ik een speciaal koraal nodig: Searing Coral. Het groeit maar op één plek: langs de kust ten zuiden van Menethil Harbor, in de Wetlands.$B$BBreng me genoeg Searing Coral, dan begin ik meteen aan het harnas. En schiet op, $N. Ik wil zo graag beginnen dat mijn tenen ervan draaien!",
  o = "Breng 20 ladingen Searing Coral naar Klockmort Spannerspan in Ironforge.",
  p = "Hallo hallo, $N! Heb je het Searing Coral? Ik kan niet wachten om aan het werk te gaan!",
  c = "Dat is het spul! Goed gedaan! Nu ga ik dit smelten en hameren. Dan kan ik de techniek van Furen samen met mijn eigen techniek gebruiken, en dan zien we wat er gebeurt!$B$BO jee, o jee! Ik weet gewoon dat het harnas heel heel heel sterk wordt!",
  g = { {"ijzeren", "iron (adj.)"}, {"koraal", "coral"}, {"af te maken", "to finish (afmaken)"}, {"kust", "coast"}, {"meteen", "right away"}, {"schiet op", "hurry up (opschieten)"}, {"tenen", "toes (teen)"}, {"draaien", "to twist, to turn"}, {"ladingen", "loads (lading)"}, {"smelten", "to smelt, to melt"}, {"hameren", "to hammer"} },
},

[1706] = { en = "Grimand's Armor", tier = 2,
  t = "Het harnas van Grimand",
  c = "Ik kan het bijna niet geloven! De techniek van Furen is gelukt. Dit harnas moet enorm veel druk kunnen weerstaan.$b$bAlsjeblieft, $n. En bedankt. Ik had de ontdekking van Furen nooit geloofd, als jij niet de materialen had verzameld die ik nodig had om het zelf te testen.",
  g = { {"bijna", "barely, almost"}, {"gelukt", "succeeded (lukken)"}, {"enorm", "tremendous, huge"}, {"druk", "stress, pressure"}, {"weerstaan", "to withstand"}, {"verzameld", "gathered (verzamelen)"} },
},

[1709] = { en = "Klockmort's Creation", tier = 2,
  t = "De creatie van Klockmort",
  c = "Hier is je harnas, $N. Het proces van Furen werkte briljant! Perfect! Echt wonderbaarlijk!$B$BJe kunt met een belegeringsmachine over dit harnas heen rijden, en het springt meteen terug in vorm!",
  g = { {"creatie", "creation"}, {"proces", "process"}, {"briljant", "brilliantly"}, {"wonderbaarlijk", "marvellous(ly)"}, {"belegeringsmachine", "siege engine"}, {"springt ... terug", "springs back (terugspringen)"}, {"vorm", "shape"} },
},

[1710] = { en = "Sunscorched Shells", tier = 2,
  t = "Zonverschroeide schalen",
  d = "Mijn collega Furen Longbeard heeft een ontdekking gedaan die ik graag wil testen. Ik wil het proberen op een nieuw harnas dat ik onderzoek. Want ik geloof dat de technieken van Furen betere resultaten geven.$B$BWil je me helpen? Als jij verzamelt wat ik nodig heb voor het harnas, maak ik een extra stuk voor jou.$B$BIk heb de door de zon verschroeide eierschalen nodig van de Highperch Wyverns die in Highperch wonen, in Thousand Needles. Zoek de schalen onder hun nesten. Kom terug als je er genoeg hebt.",
  o = "Breng 20 Sunscorched Shells naar Mathiel in Darnassus.",
  p = "Heb je de schalen, $N? Ze zijn erg sterk. Ik kan er een lak van maken, en daarmee bedek ik de ringen van mijn nieuwe maliënkolder.",
  c = "Ah, dank je. Deze zijn uitstekend!$B$BIk begin meteen aan het harnas...",
  g = { {"zonverschroeide", "sunscorched"}, {"schalen", "shells (schaal)"}, {"onderzoek", "am researching (onderzoeken)"}, {"resultaten", "results (resultaat)"}, {"verschroeide", "scorched (verschroeien)"}, {"eierschalen", "eggshells (eierschaal)"}, {"nesten", "nests (nest)"}, {"lak", "lacquer, varnish"}, {"bedek", "coat, cover (bedekken)"}, {"ringen", "rings, links (ring)"}, {"uitstekend", "excellent, splendid"} },
},

[1711] = { en = "Mathiel's Armor", tier = 2,
  t = "Het harnas van Mathiel",
  c = "Ik ben klaar met je harnas, en ik ben er erg tevreden over. De nieuwe technieken van Furen pasten perfect bij die van mij. Ik weet zeker dat dit harnas heel sterk zal blijken.$B$BDank je, $N. Moge het je goed dienen in toekomstige gevechten.",
  g = { {"tevreden", "pleased, satisfied"}, {"pasten ... bij", "fitted with, meshed with (passen bij)"}, {"blijken", "to prove, to turn out"}, {"dienen", "to serve"}, {"toekomstige", "future"}, {"gevechten", "battles (gevecht)"} },
},

[1718] = { en = "The Islander", tier = 2,
  t = "De eilandbewoner",
  d = "Je faam als krijger groeit, $N. Nu is het tijd om het op te nemen tegen je gelijken en te zien waar je staat.$B$BEr ligt een eiland voor de kust van de Barrens, ten zuiden van Ratchet. Het heet Fray Island. Het is een plek waar krijgers elkaar ontmoeten.$B$BOntmoeten, en vechten.$B$BPraat met de hoofdkrijger van Fray Island, Klannoc Macleod. Als hij je waardig vindt, leidt Klannoc je verder op het pad van de krijger.$B$BOm Fray Island te bereiken, zoek je de ondiepe zandbanken langs de Merchant Coast.",
  o = "Praat met Klannoc Macleod.",
  c = "Hallo, krijger. Fijn dat je Fray Island hebt bereikt. Ik hoop dat het je hier bevalt...",
  g = { {"eilandbewoner", "islander"}, {"faam", "renown, fame"}, {"het op te nemen tegen", "to take on, to compete with"}, {"gelijken", "peers, equals"}, {"hoofdkrijger", "chief warrior"}, {"waardig", "worthy"}, {"leidt", "leads (leiden)"}, {"bereiken", "to reach"}, {"ondiepe", "shallow"}, {"zandbanken", "sand bars (zandbank)"}, {"bevalt", "pleases, suits (bevallen)"} },
},

[1719] = { en = "The Affray", tier = 2,
  t = "De Affray",
  d = "Als je van mij wilt leren, moet je eerst de Affray doorstaan. Dat is een uitdaging die wij op Fray Island graag geven aan opkomende krijgers die denken dat ze taai zijn. Als je deze test haalt, weet ik dat je het bent.$B$BOm te beginnen loop je naar het midden van die menigte daar. Stap op het rooster. Dan weet Twiggy Flathead dat je klaar bent, en hij stuurt uitdagers op je af.$B$BVersla alle uitdagers, dan roept hij Big Will. Dood Big Will en kom binnen de tijd terug naar mij.",
  o = "Dood Big Will en praat daarna met Klannoc Macleod op Fray Island.",
  p = "Heb je je uitdaging gehaald?",
  c = "Goed gedaan, $N. Je hebt de Affray doorstaan!$B$BJe bent een waardige krijger, en het is een eer om je les te geven...",
  e = "Stap op het rooster om de Affray te beginnen",
  g = { {"doorstaan", "to pass, to get through"}, {"opkomende", "rising, up-and-coming"}, {"midden", "middle"}, {"menigte", "crowd"}, {"rooster", "grate"}, {"uitdagers", "challengers (uitdager)"}, {"stuurt ... op je af", "sends against you (afsturen op)"}, {"versla", "beat (verslaan)"}, {"waardige", "worthy"} },
},

[1791] = { en = "The Windwatcher", tier = 2,
  t = "De Windwatcher",
  d = "Je hebt nu je berserkershouding geleerd. Dan wil je er ook een goed wapen bij.$B$BPraat met Bath'rah the Windwatcher, een trollenkluizenaar die tussen de Alterac Mountains en de Western Plaguelands woont. Hij is een goede wapenmaker en een machtige sjamaan.$B$BOm Bath'rah te vinden, ga je naar de rivier die langs de oostkant van Tarren Mill stroomt. Volg die naar het noorden. Bath'rah kampeert bij ruïnes op de oostelijke oever van de rivier.",
  o = "Praat met Bath'rah the Windwatcher.",
  c = "Je hebt een lange reis gemaakt, jonge krijger. Ik zie vuur in je ogen. Je zoekt een wapen met grote kracht, ja?$B$BIk kan je helpen met jouw zoektocht. En jij kunt mij helpen met de mijne.",
  g = { {"berserkershouding", "berserker stance"}, {"trollenkluizenaar", "troll hermit"}, {"wapenmaker", "weapon maker"}, {"machtige", "powerful"}, {"sjamaan", "shaman"}, {"oostkant", "eastern side, flank"}, {"stroomt", "flows (stromen)"}, {"kampeert", "camps (kamperen)"}, {"ruïnes", "ruins (ruïne)"}, {"oever", "bank, shore"}, {"zoektocht", "quest, search"} },
},

})

